/* Generated by scripts/build.py. */
const CACHE = "__CACHE_VERSION__";
const PRECACHE = __PRECACHE__;
const BASE_PATH = "__BASE_PATH__";

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)).then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((key) => key !== CACHE).map((key) => caches.delete(key)))
    ).then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(
      fetch(request, { cache: "no-store" }).catch(() =>
        caches.match(BASE_PATH + "index.html").then((cached) => cached || caches.match(BASE_PATH))
      )
    );
    return;
  }

  // Network-first so a rebuild is picked up immediately; fall back to the
  // cache when offline. Cache-first here would keep serving stale CSS/JS
  // even after the user clears their browser cache.
  event.respondWith(
    fetch(request, { cache: "no-store" })
      .then((response) => {
        if (response && response.ok) {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
        }
        return response;
      })
      .catch(() => caches.match(request))
  );
});
